<?php
namespace App\Services;
use Illuminate\Support\Facades\{Crypt,DB};
use Carbon\CarbonImmutable as Date;
final class DeliveryDescriptions {
 public static function for(object $row,array $s):object{
  try{$p=json_decode(Crypt::decryptString($row->payload),true);$kind=$p['kind']??'booking';$row->channel=$p['channel']??'email';$labels=['guest_invite'=>'Vendégfiók-meghívó','review_request'=>'Értékeléskérés','message'=>'Üzenet értesítése','platform_message'=>'Üzemeltetői üzenet','provider_reset'=>'Szolgáltatói jelszó-visszaállítás','guest_auth'=>'Vendégfiók biztonsági levele','waitlist_verify'=>'Várólistás jelentkezés megerősítése','waitlist_available'=>'Szabad időpont a várólistáról','group_notice'=>'Csoportos óra elmaradása'];$events=['created'=>'Új foglalás visszaigazolása','confirmed'=>'Foglalás elfogadása','updated'=>'Foglalás módosítása','cancelled'=>'Foglalás lemondása','reminder'=>'Időpont előtti emlékeztető','no_show'=>'Meg nem jelenés'];$row->description=$labels[$kind]??($events[$p['event']??'']??'Foglalási értesítés');$audience=$p['audience']??(in_array($kind,['group_notice','provider_reset'],true)||($kind==='message'&&empty($p['guest']))?'provider':($p['recipientType']??'guest'));$row->audience=$audience==='provider'?'Szolgáltató':'Vendég';$row->related='';$b=collect($s['bookings'])->firstWhere('id',$p['bookingId']??'');if($b)$row->related=$b['name'].' · '.Date::parse($b['start'])->setTimezone('Europe/Budapest')->format('Y.m.d. H:i');$recipient=$p['recipient']??'';if($kind==='guest_invite'){$invite=DB::table('guest_invitations')->where('provider_id',app(Tenant::class)->id)->find($p['invitationId']??'');if($invite)$recipient=json_decode(Crypt::decryptString($invite->payload),true)['recipient']??'';}$row->recipient=str_contains($recipient,'@')?mb_substr($recipient,0,2).'***@'.explode('@',$recipient)[1]:($recipient?mb_substr($recipient,0,4).'…'.mb_substr($recipient,-3):'A kapcsolódó értesítés címzettje');}catch(\Throwable){$row->description='Nem olvasható küldési feladat';$row->channel='';$row->recipient='';$row->related='';$row->audience='';}unset($row->payload);return $row;
 }
}
